class Solution {
public:
    int deleteAndEarn(vector<int>& nums) {
        if (nums.empty()) return 0;
        int maxVal = *max_element(nums.begin(), nums.end());
        vector<int> points(maxVal + 1, 0);
        for (int x : nums) points[x] += x;
        int prev2 = 0, prev1 = 0;
        for (int val : points) {
            int curr = max(prev1, prev2 + val);
            prev2 = prev1;
            prev1 = curr;
        }
        return prev1;
    }
};

class Solution {
    public int deleteAndEarn(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        int maxVal = 0;
        for (int x : nums) if (x > maxVal) maxVal = x;
        int[] points = new int[maxVal + 1];
        for (int x : nums) points[x] += x;
        int prev2 = 0, prev1 = 0;
        for (int val : points) {
            int curr = Math.max(prev1, prev2 + val);
            prev2 = prev1;
            prev1 = curr;
        }
        return prev1;
    }
}

var deleteAndEarn = function(nums) {
    if (!nums || nums.length === 0) return 0;
    let maxVal = 0;
    for (const x of nums) if (x > maxVal) maxVal = x;
    const points = new Array(maxVal + 1).fill(0);
    for (const x of nums) points[x] += x;
    let prev2 = 0, prev1 = 0;
    for (const val of points) {
        const curr = Math.max(prev1, prev2 + val);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
};
